    16→async function updatePdfContentMassive(req, res) {
    17→    try {
    18→        const company = await getCompany(req.body.company_id);
    19→        if (!company) {
    20→            return res.status(400).send({ status: false, message: "API KEY incorrecta" });
    21→        }
    22→
    23→        const companyPackages = await getCompanyPackages(company.company_id);
    24→        if (!companyPackages) {
    25→            return res.status(400).send({ status: false, message: "No tiene paquetes asignados" });
    26→        }
    27→
    28→        const storage = await service.getStorageUsed(company.company_id);
    29→        if (isStorageExceeded(company, storage)) {
    30→            return res.status(400).send({ status: false, message: "Se ha superado la capacidad de almacenamiento. Por favor, actualice su plan." });
    31→        }
    32→
    33→        const signers_count = req.body.data.length;
    34→
    35→        await processMassivePdfModification(req, res, company, signers_count);
    36→
    37→    } catch (error) {
    38→        console.error('Error updating PDF:', error);
