    46→async function processMassivePdfModification(req, res, company, signers_count) {
    47→    const arrData = req.body.data;
    48→    const fields = req.body.fields;
    49→
    50→    const details = await db.document_packages_details.findMany({
    51→        where: {
    52→            document_package_header_id: parseInt(req.body.documentHeaderId),
    53→            active: "1",
    54→        },
    55→        select: {
    56→            id: true,
    57→            name: true,
    58→            content: true,
    59→        },
    60→    });
    61→
    62→    if (!details || details.length === 0) {
    63→        return res.status(400).json({ status: false, message: 'No se encontraron documentos PDF' });
    64→    }
    65→
    66→    const pdfBuffers = {};
    67→    for (const detail of details) {
    68→        const buffer = await axios.get(detail.content, {
    69→            responseType: 'arraybuffer'
    70→        }).then(response => Buffer.from(response.data));
    71→        pdfBuffers[detail.id] = buffer;
    72→    }
    73→
    74→    const documentPackageHeader = await db.document_packages_header.findFirst({
    75→        where: {
    76→            id: parseInt(req.body.documentHeaderId),
    77→        },
    78→        select: {
    79→            name: true,
    80→            order: true,
    81→            group_signers: {
    82→                select: {
    83→                    user_id: true,
    84→                    order: true,
    85→                    user: {
    86→                        select: {
    87→                            id: true,
    88→                            email: true,
    89→                            firstname: true,
    90→                            lastname: true,
    91→                            id_number: true,
    92→                            id_type: true,
    93→                        }
    94→                    }
    95→                },
    96→            }
    97→        }
    98→    });
    99→
   100→    res.setHeader('Content-Type', 'text/event-stream');
   101→    res.setHeader('Cache-Control', 'no-cache');
   102→    res.setHeader('Connection', 'keep-alive');
   103→    res.setHeader('X-Accel-Buffering', 'no');
   104→    res.flushHeaders();
   105→
   106→    const sendEvent = (eventName, data) => {
   107→        res.write(`event: ${eventName}\ndata: ${JSON.stringify(data)}\n\n`);
   108→    };
   109→
   110→    const total = arrData.length;
   111→    let processed = 0;
   112→    let failed = 0;
   113→    const BATCH_SIZE = 5;
   114→
   115→    sendEvent('progress', { processed: 0, total, failed: 0 });
   116→
   117→    try {
   118→        async function processOneRecord(obj) {
   119→            let signer_fields = obj.signers;
   120→
   121→            const predefinedSigners = documentPackageHeader.group_signers.map(signer => ({
   122→                signer_order: signer.order,
   123→                user_id: signer.user.id,
   124→                nombres: signer.user.firstname,
   125→                apellidos: signer.user.lastname,
   126→                correo: signer.user.email,
   127→                documento: signer.user.id_number,
   128→                tipo_documento: signer.user.id_type,
   129→            }));
   130→
   131→            signer_fields = [
   132→                ...signer_fields,
   133→                ...predefinedSigners.filter(predefSigner =>
   134→                    !signer_fields.some(signer => signer.user_id === predefSigner.user_id)
   135→                )
   136→            ];
   137→
   138→            const variableValues = obj.variableValues || {};
   139→
   140→            const s3Keys = [];
   141→            for (const detail of details) {
   142→                const detailFields = fields.filter(f => {
   143→                    if (f.pdfId === undefined || f.pdfId === null) return true;
   144→                    return parseInt(f.pdfId) === parseInt(detail.id);
   145→                });
   146→
   147→                const pdfDoc = await PDFDocument.load(pdfBuffers[detail.id]);
   148→                const modifiedPdf = await modifyPdfWithFields(pdfDoc, detailFields, signer_fields, variableValues);
   149→                const s3Key = await uploadToS3(modifiedPdf, company.id);
   150→                s3Keys.push({ detailId: detail.id, s3Key, name: detail.name });
   151→            }
   152→
   153→            await db.$transaction(async (prisma) => {
   154→                const users = await getUsers(prisma, signer_fields, company.id);
   155→
   156→                const documentPackageSigner = await createDocumentPackageSigner(
   157→                    prisma,
   158→                    obj,
   159→                    req.body.user_id_creator,
   160→                    company.id,
   161→                    users[0].id,
   162→                    req.body.documentHeaderId,
   163→                    req.body.recipients,
   164→                    req.body.sendReminder,
   165→                    req.body.reminder_days_interval
   166→                );
   167→
   168→                await prisma.document_packages_signers_logs.create({
   169→                    data: {
   170→                        document_package_signer_id: parseInt(documentPackageSigner.id),
   171→                        event_description: "Solicitud de firma enviada",
   172→                        ip_address: req.ip ? req.ip : null,
   173→                        performed_by_user_id: parseInt(req.body.user_id_creator),
   174→                        created_at: new Date(),
   175→                    },
   176→                });
   177→
   178→                for (const { s3Key, detailId, name } of s3Keys) {
   179→                    await prisma.document_packages_signers_details_values.create({
   180→                        data: {
   181→                            document_package_detail_id: detailId,
   182→                            document_package_signer_id: parseInt(documentPackageSigner.id),
   183→                            name: name,
   184→                            company_id: parseInt(documentPackageSigner.company_id),
   185→                            visibility: 1,
   186→                            document_type_id: 1,
   187→                            fields: JSON.stringify(fields),
   188→                            signers_fields: JSON.stringify(signer_fields),
   189→                            modified_content: s3Key,
   190→                            s3_key: s3Key,
   191→                            created_at: new Date(),
   192→                            updated_at: new Date()
   193→                        }
   194→                    });
   195→                }
   196→
   197→                await sendSignRequests(res, documentPackageSigner, users, company, signer_fields, req.body.name, documentPackageHeader, prisma, req.body.signerSchedules);
   198→            }, {
   199→                maxWait: 100000,
   200→                timeout: 100000,
   201→            });
   202→        }
   203→
   204→        for (let i = 0; i < total; i += BATCH_SIZE) {
   205→            const batch = arrData.slice(i, i + BATCH_SIZE);
   206→            const results = await Promise.allSettled(
   207→                batch.map(obj => processOneRecord(obj))
   208→            );
   209→
   210→            results.forEach(result => {
   211→                if (result.status === 'fulfilled') {
   212→                    processed++;
   213→                } else {
   214→                    failed++;
   215→                    console.error('Error processing record:', result.reason);
   216→                }
   217→            });
   218→
   219→            sendEvent('progress', { processed, total, failed });
   220→        }
   221→
   222→        sendEvent('complete', {
   223→            status: true,
   224→            count: processed,
   225→            failed,
   226→            total,
   227→            message: "Solicitud enviada exitosamente"
   228→        });
   229→
   230→        res.end();
   231→
   232→    } catch (error) {
   233→        console.error('Error processing massive PDF modification:', error);
   234→        sendEvent('error', { message: 'Error en la modificación masiva del PDF' });
   235→        res.end();
   236→    }
   237→}
