   239→async function modifyPdfWithFields(pdfBuffer, fields, signer_fields, variableValues = {}) {
   240→    const pdfDoc = pdfBuffer;
   241→    const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
   242→    const timesRomanFont = await pdfDoc.embedFont(StandardFonts.TimesRoman);
   243→    const timesRomanBoldFont = await pdfDoc.embedFont(StandardFonts.TimesRomanBold);
   244→    const timesRomanItalicFont = await pdfDoc.embedFont(StandardFonts.TimesRomanItalic);
   245→    const timesRomanBoldItalicFont = await pdfDoc.embedFont(StandardFonts.TimesRomanBoldItalic);
   246→    const helveticaBoldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
   247→    const helveticaObliqueFont = await pdfDoc.embedFont(StandardFonts.HelveticaOblique);
   248→    const helveticaBoldObliqueFont = await pdfDoc.embedFont(StandardFonts.HelveticaBoldOblique);
   249→
   250→    const signatureFields = fields.filter(f => f.type !== 'variable');
   251→    const variableFieldsList = fields.filter(f => f.type === 'variable');
   252→
   253→    await Promise.all(signatureFields.map(async (field) => {
   254→        const { pageNumber, top, left, width, height, name } = field;
   255→        const page = pdfDoc.getPage(pageNumber - 1);
   256→        const textWidth = helveticaFont.widthOfTextAtSize(name, 12);
   257→        const textHeight = helveticaFont.heightAtSize(12);
   258→
   259→        const x = left + (width / 2) - (textWidth / 2) - 15;
   260→        const y = page.getHeight() - top - (height / 2) - (textHeight / 4);
   261→
   262→        page.drawText(name, {
   263→            x: x,
   264→            y: y + 8,
   265→            size: 12,
   266→            font: helveticaFont
   267→        });
   268→
   269→        const signer = signer_fields.find(s => `[$FIRMA${s.signer_order}]` == name);
   270→
   271→        if (signer) {
   272→            const fullName = `${signer.nombres} ${signer.apellidos}`;
   273→            const docType = await getDocumentTypeName(signer.tipo_documento);
   274→            const docTypeAndNumber = `${docType.abbreviation}: ${signer.documento}`;
   275→
   276→            const fullNameWidth = timesRomanFont.widthOfTextAtSize(fullName, 10);
   277→            const docTypeAndNumberWidth = timesRomanFont.widthOfTextAtSize(docTypeAndNumber, 10);
   278→
   279→            const xFullName = x + (textWidth / 2) - (fullNameWidth / 2);
   280→
   281→            const xDocTypeAndNumber = x + (textWidth / 2) - (docTypeAndNumberWidth / 2);
   282→
   283→            page.drawText(fullName, {
   284→                x: xFullName,
   285→                y: y - textHeight - 8,
   286→                size: 10,
   287→                font: timesRomanFont
   288→            });
   289→
   290→            page.drawText(docTypeAndNumber, {
   291→                x: xDocTypeAndNumber,
   292→                y: y - textHeight - 22,
   293→                size: 10,
   294→                font: timesRomanFont
   295→            });
   296→        }
   297→    }));
   298→
   299→    for (const field of variableFieldsList) {
   300→        const { pageNumber, top, left, width, height, name, fontFamily, fontColor, fontWeight, fontStyle } = field;
   301→        const page = pdfDoc.getPage(pageNumber - 1);
   302→
   303→        const varName = name.replace(/\[\$|\]/g, '');
   304→        const value = variableValues[varName] || '';
   305→
   306→        if (!value) continue;
   307→
   308→        const isBold = fontWeight && parseInt(fontWeight) >= 600;
   309→        const isItalic = fontStyle === 'italic';
   310→        const isSerif = !fontFamily || fontFamily.includes('Times') || fontFamily.includes('serif') || fontFamily.includes('Garamond') || fontFamily.includes('Georgia') || fontFamily.includes('Lora');
   311→
   312→        let selectedFont;
   313→        if (isSerif) {
   314→            if (isBold && isItalic) selectedFont = timesRomanBoldItalicFont;
   315→            else if (isBold) selectedFont = timesRomanBoldFont;
   316→            else if (isItalic) selectedFont = timesRomanItalicFont;
   317→            else selectedFont = timesRomanFont;
   318→        } else {
   319→            if (isBold && isItalic) selectedFont = helveticaBoldObliqueFont;
   320→            else if (isBold) selectedFont = helveticaBoldFont;
   321→            else if (isItalic) selectedFont = helveticaObliqueFont;
   322→            else selectedFont = helveticaFont;
   323→        }
   324→
   325→        const maxFontSize = Math.min(height * 0.6, 32);
   326→        let fontSize = Math.max(8, maxFontSize);
   327→
   328→        let textWidth = selectedFont.widthOfTextAtSize(value, fontSize);
   329→        while (textWidth > width - 4 && fontSize > 6) {
   330→            fontSize -= 0.5;
   331→            textWidth = selectedFont.widthOfTextAtSize(value, fontSize);
   332→        }
   333→
   334→        const textHeight = selectedFont.heightAtSize(fontSize);
   335→
   336→        const x = left + (width / 2) - (textWidth / 2);
   337→        const y = page.getHeight() - top - (height / 2) + (textHeight / 4);
   338→
   339→        let color = rgb(0.39, 0.39, 0.38);
   340→        if (fontColor && fontColor.startsWith('#')) {
   341→            const hex = fontColor.replace('#', '');
   342→            const r = parseInt(hex.substring(0, 2), 16) / 255;
   343→            const g = parseInt(hex.substring(2, 4), 16) / 255;
   344→            const b = parseInt(hex.substring(4, 6), 16) / 255;
   345→            color = rgb(r, g, b);
   346→        }
   347→
   348→        page.drawText(value, {
   349→            x: x,
   350→            y: y,
   351→            size: fontSize,
   352→            font: selectedFont,
   353→            color: color,
   354→        });
   355→    }
   356→
   357→    return await pdfDoc.save();
   358→}
