   372→async function uploadToS3(pdfBuffer, companyId) {
   373→
   374→    const uniqueId = crypto.randomBytes(16).toString("hex");
   375→
   376→    const key = `stored_files/${companyId}/${uniqueId}`;
   377→    const uploadParams = {
   378→        Bucket: process.env.S3_BUCKET,
   379→        Key: key,
   380→        Body: pdfBuffer,
   381→        ContentType: 'application/pdf',
   382→    };
   383→
   384→    await s3Client.send(new PutObjectCommand(uploadParams));
   385→    return key; 
   386→}
