   446→async function createDocumentPackageSigner(prisma, req, creator, companyId, userId, documentHeaderId, recipients, send_reminder, reminder_days_interval) {
   447→    const fingerprint = await generateFingerPrint();
   448→
   449→    const expires_date = new Date(req.expires_in_days);
   450→    formatted_expires_date = expires_date.toISOString();
   451→    
   452→    const current_date = new Date();
   453→    const formatted_current_date = current_date.toISOString();
   454→
   455→    const request = await prisma.document_packages_signers.create({
   456→        data: {
   457→            document_package_header_id: parseInt(documentHeaderId),
   458→            user_id: parseInt(userId),
   459→            company_id: parseInt(companyId),
   460→            status: "send",
   461→            token: "",
   462→            is_pdf: 1,
   463→            sent_sign_request_at: formatted_current_date,
   464→            fingerprint: fingerprint.replace(":", ""),
   465→            ip_address: req.ip,
   466→            from_api: 1,
   467→            user_id_creator: parseInt(creator),
   468→            active: "1",
   469→            reminder_days_interval: reminder_days_interval ? reminder_days_interval : null,
   470→            send_reminder: send_reminder == 1 ? true : false,
   471→            expires_in_days: formatted_expires_date,
   472→            created_at: new Date(),
   473→            updated_at: new Date()
   474→        }
   475→    });
   476→
   477→    if (recipients.length > 0) {
   478→        const validRecipients = recipients.filter(recipient => recipient.email && recipient.email.trim() !== '');
   479→
   480→        if (validRecipients.length > 0) {
   481→            for (let i = 0; i < validRecipients.length; i++) {
   482→                const recipient = validRecipients[i];
   483→    
   484→                await prisma.request_recipients.create({
   485→                    data: {
   486→                        document_package_signer_id: request.id,
   487→                        type: 1,
   488→                        email: recipient.email,
   489→                        created_at: new Date(),
   490→                        updated_at: new Date(),
   491→                    },
   492→                });
   493→    
   494→                await prisma.document_packages_signers_logs.create({
   495→                    data: {
   496→                        document_package_signer_id: request.id,
   497→                        event_description: `Destinatario agregado: ${recipient.email}`,
   498→                        ip_address: req.ip ? req.ip : null,
   499→                        performed_by_user_id: parseInt(creator),
   500→                        created_at: new Date(),
   501→                    },
   502→                });
   503→            }
   504→        } else {
   505→            console.log("No hay destinatarios válidos");
   506→        }
   507→    }
   508→
   509→    return request;
   510→}
