   513→async function sendSignRequests(res, documentPackageSigner, users, company, signerFields, packageName, documentPackageHeader, prisma, signerSchedules = []) {
   514→    const requests = [];
   515→    let requestSending = false;
   516→
   517→    try {
   518→        for (const user of users) {
   519→            const token = service.createCustomToken({
   520→                id: user.id,
   521→                document_package_signer_id: documentPackageSigner.id,
   522→            });
   523→
   524→            const fingerprint = await generateFingerPrint();
   525→
   526→            const signerField = signerFields.find(field => field.correo.toLowerCase().trim() == user.email.toLowerCase().trim());
   527→
   528→            if (!signerField) {
   529→                console.error(`No se encontró signerField para el usuario con correo: ${user.email}`);
   530→                continue;
   531→            }
   532→
   533→            const orderMatch = signerField.signer_order;
   534→            const order = orderMatch ? parseInt(orderMatch) : users.indexOf(user) + 1;
   535→
   536→            const schedule = signerSchedules.find(s => parseInt(s.signer_order) === order);
   537→            const scheduledSendAt = schedule && schedule.send_datetime ? new Date(schedule.send_datetime) : null;
   538→            const signerStatus = scheduledSendAt ? "scheduled" : "send";
   539→
   540→            await prisma.document_signers.create({
   541→                data: {
   542→                    document_package_signer_id: documentPackageSigner.id,
   543→                    user_id: parseInt(user.id),
   544→                    order: order,
   545→                    status: signerStatus,
   546→                    token: token,
   547→                    sent_sign_request_at: new Date(),
   548→                    fingerprint: fingerprint.replace(":", ""),
   549→                    expires_in_days: documentPackageSigner.expires_in_days,
   550→                    scheduled_send_at: scheduledSendAt,
   551→                    created_at: new Date(),
   552→                    updated_at: new Date()
   553→                },
   554→            });
   555→
   556→            const url = `${process.env.ENV_URL}${token}`;
   557→
   558→            if (documentPackageHeader.order == 1 && parseInt(order) === 1) {
   559→                requests.push({
   560→                    email: user.email,
   561→                    company: company,
   562→                    firstname: user.firstname,
   563→                    lastname: user.lastname,
   564→                    passwordGenerated: genApiKey.generateApiKey({ method: "base32", dashes: false }),
   565→                    date: documentPackageSigner.expires_in_days.toLocaleDateString('es-ES'),
   566→                    time: documentPackageSigner.expires_in_days.toLocaleTimeString(),
   567→                    _url: url,
   568→                    company_email: company.email,
   569→                    sendRequest: true
   570→                });
   571→            }
   572→
   573→            if (documentPackageHeader.order === 2 && !scheduledSendAt) {
   574→                requests.push({
