   712→async function parseRecipientsFile(req, res) {
   713→    try {
   714→        if (!req.file) {
   715→            return res.status(400).json({ status: false, message: 'No se recibió ningún archivo' });
   716→        }
   717→
   718→        const workbook = new ExcelJS.Workbook();
   719→        await workbook.xlsx.readFile(req.file.path);
   720→        const sheet = workbook.worksheets[0];
   721→
   722→        const emails = [];
   723→        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
   724→
   725→        sheet.eachRow((row, rowNumber) => {
   726→            if (rowNumber === 1) return;
   727→            const cellValue = row.getCell(1).value;
   728→            let email = '';
   729→
   730→            if (cellValue && typeof cellValue === 'object') {
   731→                email = cellValue.text ? String(cellValue.text).trim() : '';
   732→            } else {
   733→                email = cellValue ? String(cellValue).trim() : '';
   734→            }
   735→
   736→            if (email && emailRegex.test(email)) {
   737→                emails.push(email);
   738→            }
   739→        });
   740→
   741→        fs.unlink(req.file.path, () => {});
   742→
   743→        if (emails.length === 0) {
   744→            return res.status(400).json({ status: false, message: 'No se encontraron correos válidos en el archivo' });
   745→        }
   746→
   747→        res.json({ status: true, emails });
   748→    } catch (error) {
   749→        console.error('Error parseando archivo de remitentes:', error);
   750→        res.status(500).json({ status: false, message: 'Error procesando el archivo' });
   751→    }
   752→}
