   177→function decodeToken(token) {
   178→    const decoded = new Promise((resolve, reject) => {
   179→        try {
   180→            const payload = jwt.decode(token, process.env.SESSION_SECRET);
   181→
   182→            if (payload.exp <= moment().unix()) {
   183→                reject({
   184→                    status: 401,
   185→                    message: "El token ha expirado",
   186→                });
   187→            }
   188→            resolve(payload.sub);
   189→        } catch (err) {
   190→            reject({
   191→                status: 500,
   192→                message: "Token No Valido",
   193→            });
   194→        }
   195→    });
   196→
   197→    return decoded;
   198→}
