    45→function buildTree(list) {
    46→  const map = {};
    47→  list.forEach(item => {
    48→    map[item.id] = { ...item, children: [] }; 
    49→  });
    50→
    51→  const roots = [];
    52→  list.forEach(item => {
    53→    if (item.parent_id && map[item.parent_id]) {
    54→      map[item.parent_id].children.push(map[item.id]);
    55→    } else {
    56→      roots.push(map[item.id]);
    57→    }
    58→  });
    59→
    60→  return roots;
    61→}
