   217→async function isCircularMove(idToMove, newParentId) {
   218→    if (newParentId === null) {
   219→        return false; 
   220→    }
   221→
   222→    let currentId = newParentId;
   223→    while (currentId !== null) {
   224→        if (currentId === idToMove) {
   225→            return true;
   226→        }
   227→        
   228→        const parent = await db.document_packages_header.findUnique({
   229→            where: { id: currentId },
   230→            select: { parent_id: true }
   231→        });
   232→
   233→        if (!parent) {
   234→            break;
   235→        }
   236→
   237→        currentId = parent.parent_id ? Number(parent.parent_id) : null;
   238→    }
   239→    return false;
   240→}
